const validateShippingEntitlement = (record: Extract<PromotionIssuedProof, { stage: 'SHIPPING' }>) => {
  const { externalFacts, merchandise, shipping } = record;
  const { application } = shipping;
  if (application === undefined) {
    return Effect.void;
  }
  const ownRefs =
    application.promotionRef.tenantId === record.tenantId &&
    (application.voucherRef === undefined || application.voucherRef.tenantId === record.tenantId) &&
    (application.activation === 'VOUCHER') === (application.voucherRef !== undefined);
  const validOffer =
    application.allowedMethodRefs.some((method) => sameMethod(method, shipping.delivery.methodRef)) &&
    DateTime.isLessThanOrEqualTo(application.effectivePeriod.from, shipping.operationAt) &&
    (application.effectivePeriod.to === undefined ||
      DateTime.isLessThan(shipping.operationAt, application.effectivePeriod.to));
  if (!ownRefs || !validOffer) {
    return failure(
      'MISMATCH',
      'Shipping entitlement must retain source identities, allowed method and Effective Period',
    );
  }
  if (application.minimumMerchandise === undefined) {
    return Effect.void;
  }
  const { publication } = externalFacts;
  return publication !== undefined &&
    publication.mode === merchandise.basis.mode &&
    comparePricingExactDecimals(publication.amount, application.minimumMerchandise.amount) >= 0
    ? Effect.void
    : failure(
        'UNVERIFIABLE',
        'Shipping minimum requires authoritative published merchandise in the same resolved basis',
      );
};

const validateShippingBinding = Effect.fn('PromotionProof.shippingBinding')(function* shippingBinding(
  record: PromotionIssuedProof,
) {
  const { externalFacts, merchandise, request } = record;
  if (record.stage !== 'SHIPPING') {
    if (externalFacts.delivery !== undefined || externalFacts.publication !== undefined) {
      return yield* failure('INCOMPLETE', 'A merchandise-only proof cannot claim completed Shipping evidence');
    }
    return yield* Effect.void;
  }
  const { shipping } = record;
  if (
    !samePurchase(shipping.purchase, request.purchase) ||
    externalFacts.delivery === undefined ||
    !sameDelivery(externalFacts.delivery, shipping.delivery) ||
    shipping.delivery.offerRef.tenantId !== record.tenantId ||
    shipping.delivery.methodRef.tenantId !== record.tenantId
  ) {
    return yield* failure(
      'MISMATCH',
      'Shipping must retain the same exact purchase and selected owner-issued Delivery evidence',
    );
  }
  const publicationBinding =
    shipping.publication === undefined
      ? externalFacts.publication === undefined
      : externalFacts.publication !== undefined &&
        samePublication(shipping.publication, externalFacts.publication) &&
        shipping.publication.merchandiseProofId === shipping.merchandiseProofId &&
        shipping.publication.mode === merchandise.basis.mode;
  const identities =
    shipping.merchandiseApplicationIds.length === merchandise.applications.length &&
    shipping.merchandiseApplicationIds.every((id, index) => id === merchandise.applications[index]?.applicationId) &&
    (shipping.outcome === 'APPLIED') === (shipping.application !== undefined) &&
    (shipping.application === undefined ||
      merchandise.applications.every(
        (application) => application.applicationId !== shipping.application?.applicationId,
      ));
  if (
    !publicationBinding ||
    !identities ||
    DateTime.toEpochMillis(shipping.operationAt) !== DateTime.toEpochMillis(record.issuedAt)
  ) {
    return yield* failure(
      'MISMATCH',
      'Shipping must reference original monetary/publication proof and application identities',
    );
  }
  return yield* validateShippingEntitlement(record);
});

const validateBindings = Effect.fn('PromotionProof.bindings')(function* bindings(record: PromotionIssuedProof) {
  yield* validatePurchaseBinding(record);
  yield* validateOriginalLines(record);
  yield* validateApplications(record);
  yield* validateCompleteness(record);
  yield* validateShippingBinding(record);
});

export interface PromotionProofVerification {
  readonly at: DateTime.Utc;
  readonly claim: 'CURRENT' | 'HISTORICAL';
  readonly handle: PromotionProofHandle;
  readonly presented: Option.Option<PromotionIssuedProof>;
  readonly request: PromotionEvaluationRequest;
}

const validateShippingLineage = Effect.fn('PromotionProof.shippingLineage')(function* shippingLineage(
  port: PromotionProofOwnerPort,
  record: PromotionIssuedProof,
  input: PromotionProofVerification,
) {
  if (record.stage === 'SHIPPING') {
    const original = yield* port.loadProof(record.tenantId, record.shipping.merchandiseProofId);
    if (
      Option.isNone(original) ||
      original.value.stage !== 'MERCHANDISE' ||
      original.value.tenantId !== record.tenantId ||
      original.value.proofId !== record.shipping.merchandiseProofId ||
      !sameMerchandise(original.value.merchandise, record.merchandise) ||
      !sameRequest(original.value.request, record.request)
    ) {
      return yield* failure('MISMATCH', 'Shipping lineage must resolve the same authentic merchandise issuance');
    }
    yield* validateBindings(original.value);
    const originalBoundary = original.value.completenessEvidence.nextApplicabilityBoundary;
    if (
      !sameBasisSource(original.value.externalFacts.basisDecision, record.externalFacts.basisDecision) ||
      !sameMerchandiseSource(original.value.externalFacts.merchandiseSource, record.externalFacts.merchandiseSource) ||
      originalBoundary === undefined ||
      !DateTime.isLessThan(record.issuedAt, originalBoundary)
    ) {
      return yield* failure('STALE', 'Shipping cannot join changed or expired merchandise owner evidence');
    }
    if (
      input.claim === 'CURRENT' &&
      (original.value.generation !== record.generation || !DateTime.isLessThan(input.at, originalBoundary))
    ) {
      return yield* failure('STALE', 'Monetary owner scope changed before Shipping issuance');
    }
  }
  return yield* Effect.void;
});

const validateCurrentProof = Effect.fn('PromotionProof.current')(function* current(
  port: PromotionProofOwnerPort,
  record: PromotionIssuedProof,
  input: PromotionProofVerification,
) {
  const generation = yield* port.currentGeneration(record.tenantId);
  const boundary = record.completenessEvidence.nextApplicabilityBoundary;
  if (
    generation !== record.generation ||
    DateTime.isLessThan(input.at, record.issuedAt) ||
    boundary === undefined ||
    !DateTime.isLessThan(input.at, boundary)
  ) {
    return yield* failure(
      'STALE',
      'Owner facts or relevant applicability time changed; fresh prospective evaluation is required',
    );
  }
  const refreshed = yield* port.verifyExternalFacts(record.externalFacts, input.at);
  if (
    !sameFacts(record.externalFacts, refreshed) ||
    ![
      refreshed.basisDecision,
      refreshed.merchandiseSource,
      ...Option.toArray(Option.fromUndefinedOr(refreshed.delivery)),
      ...Option.toArray(Option.fromUndefinedOr(refreshed.publication)),
    ].every((fact) => currentAt(fact, input.at))
  ) {
    return yield* failure('STALE', 'Required external owner evidence changed or is no longer Current');
  }
  return yield* Effect.void;
});

export const verifyPromotionProof = Effect.fn('PromotionProof.verify')(function* verify(
  port: PromotionProofOwnerPort,
  input: PromotionProofVerification,
) {
  const loaded = yield* port.loadProof(input.handle.tenantId, input.handle.proofId);
  if (Option.isNone(loaded)) {
    return yield* failure('FORGED', 'No attributable owner-issued proof exists');
  }
  const record = yield* Schema.decodeUnknownEffect(Schema.toType(PromotionIssuedProofSchema), {
    onExcessProperty: 'error',
  })(loaded.value).pipe(
    Effect.mapError(
      (cause) =>
        new PromotionProofFailure({ cause, code: 'UNVERIFIABLE', reason: 'Stored issuance cannot be decoded' }),
    ),
  );
  if (
    record.tenantId !== input.handle.tenantId ||
    record.proofId !== input.handle.proofId ||
    !sameRequest(record.request, input.request) ||
    (Option.isSome(input.presented) && !sameRecord(record, input.presented.value))
  ) {
    return yield* failure(
      'MISMATCH',
      'Presented content does not match the immutable owner-issued exact purchase proof',
    );
  }
  yield* validateBindings(record);
  yield* validateShippingLineage(port, record, input);
  if (input.claim === 'HISTORICAL') {
    return { claim: 'AUTHENTIC_HISTORICAL' as const, proof: record };
  }
  yield* validateCurrentProof(port, record, input);
  return { claim: 'CURRENT' as const, proof: record };
});
